-- BASE DE TEST COMPLETE ET COHERENTE (Obsidian Logistics)
-- A lancer APRES wipe-tout.sql, et apres migration-lot28, lot29, lot30 et lot31.
-- Scenario : lancement il y a 4 semaines. Capital 600.000$ propre, achat d'un entrepot,
-- d'un logement et de vehicules, stock initial, ventes, actions illegales (surtout en sale),
-- blanchiment, paies hebdomadaires en propre, dons, contrats, arrestations.
-- Employes, roles, prix et reglages : conserves (seuls capital / seuil / taux de paie sont reglés).
-- ============================================================
alter table obsidian_comptabilite disable trigger trg_compta_lock;
create temp table _w as select date_trunc('week', now() at time zone 'Europe/Paris')::date as w0;

-- Reglages de paie et de budget
values ('default', 20, 20000, 5000, 700000, 60000)
on conflict (id) do update set commission_pct = 20, prime_seuil = 20000, prime_fixe = 5000, capital_depart = 700000, seuil_tresorerie = 60000, updated_at = now();


-- Fournisseurs (prix d'achat) : plusieurs par produit. Reference = prefere, sinon le moins cher.
delete from obsidian_fournisseurs where created_by = 'Démo';
-- Prix de vente PNJ des armes (le tableau des prix les avait a 0)
update obsidian_armes_prix set prix = 20500 where lower(trim(nom)) = lower('Fusil à pompe');
update obsidian_armes_prix set prix = 14000 where lower(trim(nom)) = lower('Pistolet lourd');
update obsidian_armes_prix set prix = 5000 where lower(trim(nom)) = lower('Grenade');

-- Stocks (quantites recalculees plus bas depuis l'historique)

-- Historique des mouvements (achats : le trigger cree la depense compta)
update obsidian_comptabilite set type_argent = 'propre' where source = 'stock' and source_id in ('71a8330a-16c1-48ce-b1c9-85eccb356a5c','785c7f67-a8f4-4c33-a188-70b2dd8ecd4b','8d0f77e1-9b09-44c1-9b53-a236fed41fcd','df394eaa-6ec1-4413-8763-ca37f2779e13','0d1415c8-4755-4b4f-86e7-671828647eb3','e0670bd4-d069-477c-a64f-59542a167d8d','d474d77a-56c4-42eb-b338-50a994b8c275','430f9ab8-765d-4488-9d02-ac98320affea','b59e4c0b-6498-400a-ac53-6d211eff0e57','a30d1cfa-4b4a-4f12-9af9-777da9b35c13','356104a2-2928-49e0-888d-d547687d58b6','65af8d74-b2cb-43e4-9c29-1e711631d8c7','d3476c00-071b-4bee-97b5-dd1cee5eb5fb','379f6263-e331-4d80-9915-3dca1338247b','7733bf4a-d605-43f8-bdc8-847e4a09f791','0383fdec-53c3-4e9d-9568-c0a074d8df42','3b10357b-6c72-466c-a8d8-2fa38cfe5426','de41026d-6b6f-47a5-8679-b1de4f245a7b','5b3ab5c6-2c01-45a6-ad9c-e7d2d78b80eb','f6016240-5d80-4598-8bbf-2aa8c457b394','fd296db5-0d11-440a-ac03-5516e6620cef','78da0507-4c2f-4253-b4b1-50a92aceb8cc','5f8ab457-e2f5-479a-8842-801ee24730e3','1ce63fc4-9420-4988-9d39-7616ce357f87','28619951-35ab-4611-85e4-6060da677a64','fa7f794b-f1aa-4c8b-9cb7-e57fc2e396bc','ce6285c8-075e-4da3-86d6-b85459c787e1','a039f31d-b045-4319-80a2-416d630859be','a93730be-babc-4aa9-aac3-31e71bc47019','6b0bf76d-5648-49d0-9096-c51caad868a2','564c00ec-eb82-489f-9c15-783c42617502','3283f1c1-254a-4e46-9b0d-0803185dcece','2c1f2da6-9dcd-49de-ae50-e9693c376365','7e571724-e0a1-443a-8252-eb3b8f66fd68');
update obsidian_stocks s set quantite = coalesce((select sum(case when m.type in ('entrée','entree') then m.quantite else -m.quantite end) from obsidian_mouvements m where m.stock_id = s.id), 0);

