-- Contrats (les termines creent une recette propre en compta, datee dans la bonne semaine)
update obsidian_comptabilite set created_at = least(((((SELECT w0 FROM _w) + -17) + time '17:00') AT TIME ZONE 'Europe/Paris'), now() - interval '10 minutes'), semaine = ((SELECT w0 FROM _w) + -21) where source = 'contrat' and source_id = '3fcc290d-0d84-4140-83fc-5d29c6e925af';
update obsidian_comptabilite set created_at = least(((((SELECT w0 FROM _w) + -11) + time '17:00') AT TIME ZONE 'Europe/Paris'), now() - interval '10 minutes'), semaine = ((SELECT w0 FROM _w) + -14) where source = 'contrat' and source_id = '334216f8-807c-46e5-8ebc-063fa158f3ee';
update obsidian_comptabilite set created_at = least(((((SELECT w0 FROM _w) + -9) + time '17:00') AT TIME ZONE 'Europe/Paris'), now() - interval '10 minutes'), semaine = ((SELECT w0 FROM _w) + -14) where source = 'contrat' and source_id = '9f6150cb-3920-42c1-be34-70f137c95005';
update obsidian_comptabilite set created_at = least(((((SELECT w0 FROM _w) + -6) + time '17:00') AT TIME ZONE 'Europe/Paris'), now() - interval '10 minutes'), semaine = ((SELECT w0 FROM _w) + -7) where source = 'contrat' and source_id = '4b3197cd-2f94-4be4-91f5-359192790549';
update obsidian_comptabilite set created_at = least(((((SELECT w0 FROM _w) + -4) + time '17:00') AT TIME ZONE 'Europe/Paris'), now() - interval '10 minutes'), semaine = ((SELECT w0 FROM _w) + -7) where source = 'contrat' and source_id = '90437798-da1a-4c23-91dd-90d3e586662f';

