-- Dons (argent remis a l'entreprise) : 2 valides, 1 en attente, 1 refuse
select obsidian_don_valider('6da69b2d-dbda-490d-8d97-7b24334f69ac', 'Pierce Davenport', true);
select obsidian_don_valider('649a8d14-cfea-464d-a08c-f68031cb2127', 'Pierce Davenport', true);
select obsidian_don_valider('58a11e88-d581-4291-af02-ba427d28e2a3', 'Pierce Davenport', false);

-- ============================================================
-- BLOC 2 : consortium, lot 35 et modules annexes (1 mois d'activite coherente)
-- ============================================================

-- Nouvelles actions du lot 35 (semaine en cours, donc pas encore dans une paie)
select 'recette', action, montant, type_argent, action || ' - ' || membre, membre, date_trunc('week', created_at at time zone 'Europe/Paris')::date, created_by, created_at, 'action', id
from actions_illegales where id::text like 'a0000001-%';

-- Taxes (accords avec des groupes) + paiements + recettes compta
select 'recette','Taxe',p.montant,p.type_argent,'Taxe - ' || t.groupe || ' - ' || t.raison,'Pierce Davenport',
       date_trunc('week', p.created_at at time zone 'Europe/Paris')::date,'Pierce Davenport',p.created_at,'taxe',p.id
from obsidian_taxes_paiements p join obsidian_taxes t on t.id = p.taxe_id where p.created_by = 'Démo';

-- Recrutement (fiches candidats)

-- Votes des membres : les fiches validees ont la majorite, les candidats ont quelques votes
select r.id, e.id::text, e.nom,
       case when r.statut in ('valide','dossier') then 'approuve' when r.statut = 'refuse' then 'refuse' when (row_number() over (partition by r.id order by e.nom)) % 2 = 0 then 'approuve' else 'refuse' end,
       r.created_at + interval '1 day'
from obsidian_recrutement r
join lateral (select id, nom from obsidian_employes order by nom limit (case when r.statut = 'candidat' then 3 else 6 end)) e on true
where r.created_by = 'Démo';

-- Guerres / GDT

-- Base de donnees : personnes + vehicules
select pl, mo, co, (select id from bdd_personnes where nom = ow and notes_privees='Démo' limit 1), 'Démo'
from (values ('VNT-204','Kuruma','Noir','Okafor'),('GHO-777','Sultan','Gris','Kowalski'),('MDM-013','Bison','Rouge','Ramirez'),('BDS-001','Cognoscenti','Blanc','Moretti'),('WHT-555','Rebel','Vert','Whitaker')) v(pl,mo,co,ow);

-- Fiches (creees par les membres, repartition pour le classement d'activite)
select p.prenom || ' ' || p.nom, 'personne', p.priorite, p.statut, 'civil', array['démo'], p.age, p.origine, p.organisation, p.occupation, p.telephone, p.notes_publiques, 'Fiche de démonstration.',
       case when p.statut = 'Recherché' then 25000 else 0 end, p.statut = 'Surveillé',
       (array['Adrian Vance','Lucas Bennett','Camille Roux','Elena Moretti','Adrian Vance','Lucas Bennett'])[(row_number() over (order by p.nom))::int],
       now() - ((row_number() over (order by p.nom)) * interval '3 days')
from bdd_personnes p where p.notes_privees = 'Démo';
select id, nom, 'Fiche créée', created_by from obsidian_fiches where 'démo' = any(tags);

-- Consortium : reputation, pactes, audits, tribunal, evenements (30 derniers jours)
select o, (array[-15,-8,-3,4,6,10,12])[1+floor(random()*7)::int], (array['Respect d''un pacte','Incident en zone neutre','Livraison honorée','Violation de territoire','Aide ponctuelle','Retard de paiement'])[1+floor(random()*6)::int],
       'manuel', 'Démo', now() - (random()*30 || ' days')::interval
from generate_series(1,40) g, lateral (select (array['La Main de Minuit','WBS','VenTa','Ghost Chain','Black Diamond Society','The Black Order','Spartan','Lost Verity'])[1+floor(random()*8)::int] o) x;
select o, n, (case when n >= 8 then 'Excellent' when n >= 5 then 'Correct' else 'Insuffisant' end), 'Audit de démonstration.', 'Démo', now() - (random()*28 || ' days')::interval
from (values ('La Main de Minuit',8),('WBS',6),('VenTa',9),('Ghost Chain',4),('Black Diamond Society',7),('The Black Order',3),('Lost Verity',5),('Spartan',8)) v(o,n);
update gm_pactes set groupe_id=(select id from carte_gangs c where c.nom=organisation) where created_by='Démo' and groupe_id is null;
update gm_audits set groupe_id=(select id from carte_gangs c where c.nom=organisation) where created_by='Démo' and groupe_id is null;
update gm_reputation_log set groupe_id=(select id from carte_gangs c where c.nom=organisation) where created_by='Démo' and groupe_id is null;
update tribunal_dossiers set groupe_id=(select id from carte_gangs c where c.nom=organisation) where created_by='Démo' and groupe_id is null;
update gm_evenements set groupe_id=(select id from carte_gangs c where c.nom=partenaire) where created_by='Démo' and groupe_id is null;

-- Cloture des semaines passees
select obsidian_cloturer_semaines('seed');
alter table obsidian_comptabilite enable trigger trg_compta_lock;

-- Controle : tresorerie par type d'argent (capital inclus dans le champ capital)
select obsidian_budget() as budget;
